import{_ as d,o as a,c as o,ag as r}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"アーキテクチャ比較","description":"","frontmatter":{},"headers":[],"relativePath":"ja/evolution/comparison.md","filePath":"ja/evolution/comparison.md","lastUpdated":null}'),e={name:"ja/evolution/comparison.md"};function l(i,t,n,p,h,s){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="アーキテクチャ比較" tabindex="-1">アーキテクチャ比較 <a class="header-anchor" href="#アーキテクチャ比較" aria-label="Permalink to &quot;アーキテクチャ比較&quot;">​</a></h1><p>Polyrepo と Monorepo の多次元比較。</p><h2 id="サマリー" tabindex="-1">サマリー <a class="header-anchor" href="#サマリー" aria-label="Permalink to &quot;サマリー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>次元</th><th>Polyrepo</th><th>Monorepo</th></tr></thead><tbody><tr><td>リポジトリ構造</td><td>単一リポジトリ・単一アプリ</td><td>単一リポジトリ・複数パッケージ・複数アプリ</td></tr><tr><td>バージョン管理</td><td>単一 package.json</td><td>pnpm workspace catalog</td></tr><tr><td>ビルドツール</td><td>直接 vite</td><td>turbo + vite</td></tr><tr><td>コード再利用</td><td>手動コピー</td><td>workspace パッケージ参照</td></tr><tr><td>UI 拡張</td><td>フォークまたはコピー</td><td>apps/ に追加</td></tr><tr><td>パッケージ境界</td><td>なし（src/ 混在）</td><td>明確（パッケージ階層）</td></tr><tr><td>導入コスト</td><td>低</td><td>中</td></tr><tr><td>長期メンテナンスコスト</td><td>高</td><td>低</td></tr></tbody></table><h2 id="polyrepo-が適している場面" tabindex="-1">Polyrepo が適している場面 <a class="header-anchor" href="#polyrepo-が適している場面" aria-label="Permalink to &quot;Polyrepo が適している場面&quot;">​</a></h2><ul><li>単一製品・複数 UI 不要</li><li>小チームまたは個人プロジェクト</li><li>素早いプロトタイプ検証</li><li>プロジェクト横断のコード再利用不要</li></ul><h2 id="monorepo-が適している場面" tabindex="-1">Monorepo が適している場面 <a class="header-anchor" href="#monorepo-が適している場面" aria-label="Permalink to &quot;Monorepo が適している場面&quot;">​</a></h2><ul><li>複数 UI フレームワークまたは製品ラインのサポート</li><li>再利用可能な共有インフラが多い</li><li>統一されたエンジニアリング標準が必要なチーム開発</li><li>長期的な保守性を重視</li><li>ビルドキャッシュとタスク並列化が必要</li></ul><h2 id="移行コスト" tabindex="-1">移行コスト <a class="header-anchor" href="#移行コスト" aria-label="Permalink to &quot;移行コスト&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>工数</th><th>一回限り/継続</th></tr></thead><tbody><tr><td>pnpm workspace の理解</td><td>小</td><td>一回限り</td></tr><tr><td>Turbo 設定</td><td>小</td><td>一回限り</td></tr><tr><td>パッケージ分割</td><td>中</td><td>一回限り</td></tr><tr><td>既存コードの移行</td><td>中〜大</td><td>一回限り</td></tr></tbody></table><p>移行後：新 UI アプリ追加・共有インフラアップグレードの追加コストはほぼゼロに近づきます。</p><h2 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to &quot;結論&quot;">​</a></h2><blockquote><p>「複数 UI エコシステム + 共有インフラ + 長期進化」のシナリオでは、Monorepo がより適切な選択です。</p></blockquote><p>Fast Vue3 の移行は新技術への追従ではなく、エンジニアリング規模と要件に自然に駆動された結果です。Monorepo は「バージョン一貫性・コード再利用・エンジニアリング統一」をアーキテクチャレベルの保証にします。</p>',14)])])}const b=d(e,[["render",l]]);export{u as __pageData,b as default};
